#!/bin/zsh
cd "$(dirname "$0")/.."
P="Independent review of slides_study/main.pdf, slides_study/main.tex and slides_study/LAB_PLAN.md against slides_study/BRIEF.md. Do NOT edit main.tex, build_study.py or LAB_PLAN.md. Read the source documents the brief lists. Check: (1) every lab command against the script/tool it calls (name, flags, paths, working directory), (2) every PASS/FAIL criterion against docs/D435I_CALIBRATION_PLAN.md, slides_study/sources/LAB_DAY_2026-10-15-4b63.md and STM32_LINK_STEP, (3) evidence labels and any gate wrongly shown as PASS, (4) technical correctness of the lecture (stereo, IMU noise/Allan, frames, timestamps, ROS 2 QoS/rosbag, Kalibr, ORB-SLAM3 init, ATE/RPE), (5) whether a student could actually execute Session 1 and Session 2 in order without improvising, (6) layout: render with the swift renderer named in BRIEF.md into slides_study/qa/review-k/ and look at pages. Write findings ranked by severity with page numbers and a concrete fix for each to slides_study/REVIEW_CODEX_K.md."
CODEX_HOME="$HOME/.codex-k" codex exec -c model_reasoning_effort="high" --sandbox workspace-write --skip-git-repo-check "$P" > slides_study/logs/review-k.log 2>&1 < /dev/null
